 ('8d2485ee-344f-502e-910b-1a46ece06e4e'::uuid, 'fa2b49452a6bc75e0dc6e0cccf0ff541'),
 ('c5c2bcd4-741b-5966-b152-61e0d729d935'::uuid, '65f7e47475ae6aa9d66642562c4a80e6')),
live as (
  select d.id, md5(concat_ws('|', d.id::text, d.kind, coalesce(d.plan_key,''), coalesce(d.label,''), coalesce(d.due_date::text,''), coalesce(d.notes,''), coalesce(d.intake,''), coalesce(d.program_id::text,''), coalesce(d.source_id::text,''))) as md5
  from public.deadlines d
  join public.institutions i on i.id = d.institution_id
  where i.slug in ('adelaide', 'alberta', 'anu', 'bath', 'birmingham', 'bristol', 'calgary', 'cambridge', 'durham', 'edinburgh', 'exeter', 'imperial', 'kings-college-london', 'leeds', 'loughborough', 'lse', 'macquarie', 'manchester', 'mcgill', 'mcmaster', 'melbourne', 'monash', 'nottingham', 'oxford', 'queens-university', 'simon-fraser', 'southampton', 'sydney', 'toronto', 'ubc', 'ucl', 'unsw', 'uq', 'uts', 'uwa', 'warwick', 'waterloo', 'western-university')
),
problems as (
  select coalesce(e.id, l.id) as id,
         case when l.id is null then 'missing' when e.id is null then 'extra' else 'mismatch' end as problem
  from expected e full join live l on l.id = e.id
  where l.id is null or e.id is null or l.md5 <> e.md5
)
select id, problem from (
  select id::text as id, problem, 0 as ord from problems
  union all
  select 'total', format('%s live rows, %s expected, %s problems',
                         (select count(*) from live), (select count(*) from expected), (select count(*) from problems)), 1
) r
order by ord, id;
